#include "stdlib/math/base/assert/is_positive_zero.h"
#include <node_api.h>
#include <stdint.h>
#include <assert.h>

/**
* Add-on namespace.
*/
namespace stdlib_math_base_assert_is_positive_zero {

	/**
	* Tests if a double-precision floating-point numeric value is positive zero.
	*
	* ## Notes
	*
	* -   When called from JavaScript, the function expects one argument:
	*
	*     -    `x`: a number
	*/
	napi_value node_is_positive_zero( napi_env env, napi_callback_info info ) {
		napi_status status;

		size_t argc = 1;
		napi_value argv[ 1 ];
		status = napi_get_cb_info( env, info, &argc, argv, nullptr, nullptr );
		assert( status == napi_ok );

		if ( argc < 1 ) {
			napi_throw_error( env, nullptr, "invalid invocation. Must provide a number." );
			return nullptr;
		}

		napi_valuetype vtype0;
		status = napi_typeof( env, argv[ 0 ], &vtype0 );
		assert( status == napi_ok );

		napi_value v;
		double x;
		if ( vtype0 == napi_number ) {
			status = napi_get_value_double( env, argv[ 0 ], &x );
			assert( status == napi_ok );

			status = napi_create_int32( env, (int32_t)stdlib_base_is_positive_zero( x ), &v );
			assert( status == napi_ok );
		} else {
			status = napi_create_int32( env, 0, &v );
			assert( status == napi_ok );
		}

		return v;
	}

	napi_value Init( napi_env env, napi_value exports ) {
		napi_status status;
		napi_value fcn;
		status = napi_create_function( env, "exports", NAPI_AUTO_LENGTH, node_is_positive_zero, NULL, &fcn );
		assert( status == napi_ok );
		return fcn;
	}

	NAPI_MODULE( NODE_GYP_MODULE_NAME, Init )
} // end namespace stdlib_math_base_assert_is_positive_zero","lineStart":1,"lineEnd":80,"totalLines":80,"truncated":false}},"title":"repos/pc-lib-3456/math-base-assert-is-positive-zero/src/addon.cpp","time":{"start":1783261974250,"end":1783261974254}},"id":"prt_f32b24e22001ffvfXny0PoMB67","sessionID":"ses_0cd4dfc43ffeZc5tgasN0UQpR4","messageID":"msg_f32b23ee70018ifgOIP5R6LPgs"}}

