'use strict';

// MODULES //

var tape = require( 'tape' );
var isPositiveZero = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isPositiveZero, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided `+0`', function test( t ) {
	t.strictEqual( isPositiveZero( 0.0 ), true, 'returns expected value' );
	t.strictEqual( isPositiveZero( +0.0 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if provided `-0`', function test( t ) {
	t.strictEqual( isPositiveZero( -0.0 ), false, 'returns expected value' );
	t.end();
});

tape( 'the function returns `false` if not provided `+0`', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5.0,
		-1.0,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isPositiveZero( values[i] ), false, 'returns expected value when provided ' + values[ i ] );
	}
	t.end();
});","lineStart":1,"lineEnd":68,"totalLines":68,"truncated":false}},"title":"repos/pc-lib-3456/math-base-assert-is-positive-zero/test/test.js","time":{"start":1783261978944,"end":1783261978948}},"id":"prt_f32b260430017X8rUqTNs75rBp","sessionID":"ses_0cd4dfc43ffeZc5tgasN0UQpR4","messageID":"msg_f32b2544b001Cs4DocrEhsAc00"}}

