'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var uniform = require( '@stdlib/random-array-uniform' );
var isBoolean = require( '@stdlib/assert-is-boolean' ).isPrimitive;
var pkg = require( './../package.json' ).name;
var isPositiveZero = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var opts;
	var x;
	var y;
	var i;

	opts = {
		'dtype': 'float64'
	};
	x = uniform( 100, -5.0e6, 5.0e6, opts );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		y = isPositiveZero( x[ i%x.length ] );
		if ( typeof y !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( y ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":56,"totalLines":56,"truncated":false}},"title":"repos/pc-lib-3456/math-base-assert-is-positive-zero/benchmark/benchmark.js","time":{"start":1783261994441,"end":1783261994444}},"id":"prt_f32b29cfc001cQ79Cx6WD9NzcI","sessionID":"ses_0cd4dfc43ffeZc5tgasN0UQpR4","messageID":"msg_f32b28a65001r8o95UdLkZ0B56"}}

